//! Isolated strict-f64 physical receipts. Signed rounding is measured, not spendable.
const std=@import("std");
pub const Difference=struct{hi:f64,lo:f64};
pub fn difference(a:f64,b:f64)Difference{@setFloatMode(.strict);const hi=a-b;const v=hi-a;return .{.hi=hi,.lo=(a-(hi-v))+(-b-v)};}
pub fn downDifference(a:f64,b:f64)f64{const d=difference(a,b);return if(d.lo<0)std.math.nextAfter(f64,d.hi,0) else d.hi;}
pub fn downProduct(a:f64,b:f64)f64{@setFloatMode(.strict);if(a==0 or b==0)return 0;const product=a*b;if(!std.math.isFinite(product))return product;return std.math.nextAfter(f64,product,0);}
pub fn downRatio(a:f64,b:f64)f64{@setFloatMode(.strict);if(a<=0 or b<=0)return 0;return std.math.nextAfter(f64,a/b,0);}
pub fn upperSum(values:[4]f64)f64{@setFloatMode(.strict);var a=values;std.mem.sort(f64,&a,{},std.sort.asc(f64));var sum:f64=0;for (a)|x|if(x>0){sum=std.math.nextAfter(f64,sum+x,std.math.inf(f64));};return sum;}
pub fn canonicalSum(values:[4]f64)f64{@setFloatMode(.strict);var a=values;std.mem.sort(f64,&a,{},std.sort.asc(f64));var sum:f64=0;for (a)|x|sum+=x;return sum;}
pub const Removal=struct{after:f64,paid:f64};
pub fn remove(source:f64,request:f64)?Removal{@setFloatMode(.strict);if(!std.math.isFinite(source) or source<0 or !std.math.isFinite(request) or request<0)return null;const want=@min(source,request);var after=source-want;var d=difference(source,after);if(d.hi>want or (d.hi==want and d.lo>0)){after=std.math.nextAfter(f64,after,source);d=difference(source,after);}if(after<0 or after>source or d.hi<0)return null;return .{.after=after,.paid=downDifference(source,after)};}
pub fn ulp(x:f64)f64{return @max(std.math.nextAfter(f64,x,std.math.inf(f64))-x,x-std.math.nextAfter(f64,x,0));}
pub const Ledger=struct{signed:f64=0,absolute:f64=0,envelope:f64=0,operations:u64=0,unrepresented:f64=0};
pub fn recordTerms(l:*Ledger,terms:[10]f64,envelope:f64)void{@setFloatMode(.strict);var a=terms;std.mem.sort(f64,&a,{},std.sort.asc(f64));var value:f64=0;var diagnostic_bound:f64=0;for(a)|x|{if(x==0)continue;value+=x;diagnostic_bound=std.math.nextAfter(f64,diagnostic_bound+ulp(value),std.math.inf(f64));}l.signed+=value;const absolute_bound=std.math.nextAfter(f64,@abs(value)+diagnostic_bound,std.math.inf(f64));l.absolute=std.math.nextAfter(f64,l.absolute+absolute_bound,std.math.inf(f64));l.envelope+=envelope;l.operations+=1;}
pub fn record(l:*Ledger,source:f64,after:f64,target:f64,newtarget:f64)void{const d=difference(source,after);const c=difference(newtarget,target);recordTerms(l,.{d.hi,d.lo,-c.hi,-c.lo,0,0,0,0,0,0},ulp(source)+ulp(after)+ulp(target)+ulp(newtarget));}
pub fn transfer(source:*f64,target:*f64,want:f64,l:*Ledger)?f64{@setFloatMode(.strict);if(!std.math.isFinite(target.*) or target.*<0)return null;if(!std.math.isFinite(l.signed) or !std.math.isFinite(l.absolute) or !std.math.isFinite(l.envelope))return null;const r=remove(source.*,want) orelse return null;if(r.paid==0 and want==0)return 0;const after=target.*+r.paid;if(!std.math.isFinite(after))return null;var ledger=l.*;record(&ledger,source.*,r.after,target.*,after);if(r.paid==0 and want>0)ledger.unrepresented+=@min(source.*,want);if(!std.math.isFinite(ledger.signed) or !std.math.isFinite(ledger.absolute) or !std.math.isFinite(ledger.envelope) or !std.math.isFinite(ledger.unrepresented))return null;l.*=ledger;source.*=r.after;target.*=after;return r.paid;}
pub fn signal32(paid:f64,demand:f64)f32{if(paid<=0 or demand<=0)return 0;const h=@min(1,downRatio(paid,demand));var result:f32=@floatCast(h);if(@as(f64,result)>h)result=std.math.nextAfter(f32,result,0);return result;}
pub fn lowerSum(values:[4]f64)f64{@setFloatMode(.strict);var a=values;std.mem.sort(f64,&a,{},std.sort.asc(f64));var sum:f64=0;for (a)|x|if(x>0){sum=std.math.nextAfter(f64,sum+x,0);};return sum;}
